<div class="admin-panel-heading"><div><span class="admin-eyebrow">PUBLIC ENQUIRIES</span><h2>Contact Messages</h2></div></div><section class="admin-panel admin-list-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Sender</th><th>Subject and message</th><th>Status</th><th>Received</th><th>Update</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="5" class="admin-empty-cell">No contact messages.</td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['name']) ?></strong><small class="admin-cell-subtitle"><a href="mailto:<?= e($row['email']) ?>"><?= e($row['email']) ?></a><?php if($row['phone']): ?><br><?= e($row['phone']) ?><?php endif; ?></small></td><td><strong><?= e($row['subject']) ?></strong><p class="admin-contact-message"><?= nl2br(e($row['message'])) ?></p></td><td><?= e(ucfirst($row['status'])) ?></td><td><?= e($row['created_at']) ?></td><td><?php if(in_array('support.reply',$permissions??[],true)): ?><form method="post" action="<?= e(admin_url('cms/contacts/'.(int)$row['id'].'/status')) ?>"><?= admin_csrf_field() ?><select name="status"><?php foreach(['new','read','replied','closed'] as $status): ?><option value="<?= e($status) ?>" <?= $row['status']===$status?'selected':'' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select><button class="admin-button" type="submit">Update</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
